slides.solution:
import sqlite3

conn = sqlite3.connect(":memory:")
conn.executescript("""
    CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT);
    CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER, amount REAL);
    INSERT INTO customers (name) VALUES ('Asha'), ('Ravi'), ('Neha'), ('Kabir');
    INSERT INTO orders (customer_id, amount) VALUES
        (1, 450), (2, 1200), (1, 950), (4, 300), (2, 100), (4, 250);
""")

def top_customers(conn, n):
    query = """
        SELECT c.name, SUM(o.amount) AS total
        FROM customers c
        JOIN orders o ON o.customer_id = c.id
        GROUP BY c.id
        ORDER BY total DESC
        LIMIT ?
    """
    return conn.execute(query, (n,)).fetchall()

print(top_customers(conn, 2))   # [('Asha', 1400.0), ('Ravi', 1300.0)]
